(()=>{"use strict";(()=>{const t=document.getElementById("timer-hours"),e=document.getElementById("timer-minutes"),n=document.getElementById("timer-seconds"),o=()=>{let r=(()=>{const t=(new Date("1 july 2025").getTime()-(new Date).getTime())/1e3;return Math.floor(t/3600/24),{timeRemaining:t,hours:Math.floor(t/3600%24),minutes:Math.floor(t/60%60),seconds:Math.floor(t%60)}})();r.timeRemaining>0?(t.textContent=r.hours.toString().padStart(2,"0"),e.textContent=r.minutes.toString().padStart(2,"0"),n.textContent=r.seconds.toString().padStart(2,"0"),setInterval(o,1e3)):(t.textContent="00",e.textContent="00",n.textContent="00")};o()})()})();